          {
            "name": "Force électrostatique",
            "formula": "F = q · E",
            "note": "q en Coulombs (C), F en Newtons (N)."
          },
          {
            "name": "Vitesse acquise par un électron",
            "formula": "v = √[(2 e U) / m]",
            "note": "e = 1,6 × 10⁻¹⁹ C, m = 9,1 × 10⁻³¹ kg."
          }
